 private final Map<UUID,net.kyori.adventure.bossbar.BossBar> bars=new HashMap<>(); private HttpServer packServer; private byte[] packHash; private World world; private File playersFile; private YamlConfiguration data; private NamespacedKey npcKey; private final Random random=new Random();
 private final String[] names={"КАРЬЕР", "МЕДНЫЕ ТОННЕЛИ", "КРИСТАЛЬНЫЕ ПЕЩЕРЫ", "МАГМАТИЧЕСКАЯ ШАХТА", "БЕЗДНА"};
 private final Material[][] ores={{Material.STONE,Material.COAL_ORE,Material.IRON_ORE},{Material.STONE,Material.COPPER_ORE,Material.GOLD_ORE},{Material.DEEPSLATE,Material.LAPIS_ORE,Material.DIAMOND_ORE},{Material.NETHERRACK,Material.NETHER_GOLD_ORE,Material.EMERALD_ORE},{Material.DEEPSLATE,Material.DIAMOND_ORE,Material.ANCIENT_DEBRIS}};
